    u_xlat2.x = cos(_v_buffer0.v_cb0[6].y);
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat8.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat1.x = dot(u_xlat8.xy, u_xlat3.yz);
    u_xlat1.y = dot(u_xlat8.xy, u_xlat3.xy);
    u_xlat1.xy = u_xlat1.xy + _v_buffer0.v_cb0[6].zw;
    u_xlat1.xy = u_xlat1.xy + vec2(0.5, 0.5);
    vs_TEXCOORD2.xy = u_xlat1.xy * _v_buffer0.v_cb0[7].zw;
    u_xlat1.x = sin(_v_buffer0.v_cb0[11].z);
    u_xlat2.x = cos(_v_buffer0.v_cb0[11].z);
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat8.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat8.xy, u_xlat3.yz);
    u_xlat1.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat9 = _v_buffer0.v_cb0[23].x + _v_buffer1.v_cb1.x;
    u_xlat1.x = _v_buffer0.v_cb0[11].w * u_xlat9 + u_xlat1.x;
    u_xlat1.y = _v_buffer0.v_cb0[12].x * u_xlat9 + u_xlat1.y;
    vs_TEXCOORD4.xy = u_xlat1.xy * _v_buffer0.v_cb0[10].xy;
    u_xlat1.x = u_xlat9 * _v_buffer0.v_cb0[5].z;
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat1.x = u_xlat1.x + _v_buffer0.v_cb0[6].x;
    u_xlat1.x = u_xlat1.x * _v_buffer0.v_cb0[5].w;
#ifdef UNITY_ADRENO_ES3
