    u_xlat1.x = u_xlat1.x + -1.0;
    vs_TEXCOORD3.y = _v_buffer0.v_cb0[10].z * u_xlat1.x + 1.0;
    u_xlat1.x = u_xlat9 * _v_buffer0.v_cb0[20].y;
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat1.x = u_xlat1.x + _v_buffer0.v_cb0[20].w;
