    u_xlat1.x = u_xlat1.x + -1.0;
    vs_TEXCOORD3.w = _v_buffer0.v_cb0[20].x * u_xlat1.x + 1.0;
    u_xlat1.xy = vec2(u_xlat9) * _v_buffer0.v_cb0[16].wx;
    u_xlat5.x = sin(u_xlat1.y);
    u_xlat2.x = cos(u_xlat1.x);
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat5.x = u_xlat5.x + (-_v_buffer0.v_cb0[16].z);
    u_xlat5.x = u_xlat5.x * _v_buffer0.v_cb0[16].y;
#ifdef UNITY_ADRENO_ES3
    u_xlat5.x = min(max(u_xlat5.x, 0.0), 1.0);
#else
