#endif
    u_xlat5.x = u_xlat5.x + -1.0;
    vs_TEXCOORD3.z = _v_buffer0.v_cb0[15].w * u_xlat5.x + 1.0;
    u_xlat5.xz = _v_buffer0.v_cb0[17].xy + vec2(0.5, 0.5);
    u_xlat0.xy = u_xlat0.xy + (-u_xlat5.xz);
    u_xlat0.xy = u_xlat0.xy * _v_buffer0.v_cb0[15].yz;
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    vs_TEXCOORD5.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat0.x = sin(_v_buffer0.v_cb0[21].x);
    u_xlat1.x = cos(_v_buffer0.v_cb0[21].x);
    u_xlat2.z = u_xlat0.x;
    u_xlat2.y = u_xlat1.x;
