uniform highp sampler2D f_t6;
uniform highp sampler2D f_t7TEX_with_SMPf_s1;
uniform highp sampler2D f_t7;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec2 vs_TEXCOORD4;
in highp vec4 vs_TEXCOORD3;
in highp vec2 vs_TEXCOORD5;
in highp vec2 vs_TEXCOORD6;
in highp vec4 vs_TEXCOORD7;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat6;
float u_xlat12;
void main()
{
    u_xlat0 = texture(f_t1TEX_with_SMPf_s4, vs_TEXCOORD2.xy);
    u_xlat1.x = u_xlat0.x * _f_buffer0.f_cb0[4].w;
    u_xlat1.y = u_xlat0.y * _f_buffer0.f_cb0[5].x;
    u_xlat0.xy = u_xlat1.xy + vs_TEXCOORD7.xy;
    u_xlat1 = texture(f_t4TEX_with_SMPf_s3, u_xlat0.xy);
    u_xlat0.xyw = (-u_xlat1.xyz) + _f_buffer0.f_cb0[4].yyy;
    u_xlat4.xyz = u_xlat0.zzz * abs(u_xlat0.xyw);
    u_xlat0.x = abs(u_xlat0.x) + -0.5;
    u_xlat4.xyz = u_xlat4.xyz * _f_buffer0.f_cb0[3].xyz;
    u_xlat4.xyz = u_xlat4.xyz * _f_buffer0.f_cb0[3].www;
    u_xlat0.yzw = u_xlat4.xyz * _f_buffer0.f_cb0[4].xxx;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s2, vs_TEXCOORD0.xy);
    u_xlat0 = u_xlat0 * u_xlat1.xxxx;
    u_xlat2 = texture(f_t3TEX_with_SMPf_s5, vs_TEXCOORD4.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[9].yyy;
    u_xlat6.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[8].xyz;
    u_xlat2.x = abs(u_xlat2.x) + -0.5;
    u_xlat2.x = u_xlat1.y * u_xlat2.x;
    u_xlat2.yzw = u_xlat6.xyz * _f_buffer0.f_cb0[8].www;
    u_xlat2 = u_xlat2 * _f_buffer0.f_cb0[9].wxxx;
