    u_xlat4.xyz = u_xlat0.yzw * vs_TEXCOORD3.xxx;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat4.xyz = u_xlat4.xyz * u_xlat6.xyz + (-u_xlat3.xyz);
